contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function taking arbitrary callee and data
    function run(address callee, bytes memory data) public payable {
        require(true);

        // record C's balance before call
        uint256 before = address(c).balance;

        // perform the forward call and observe whether it reverts
        bool reverted;
        bool callReturned;
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            callReturned = false;
        } else {
            reverted = false;
            callReturned = true;
        }

        // If forward returned (did not revert) then the low-level call it made must have succeeded
        // and C's balance must not have increased.
        assert(reverted || (callReturned && address(c).balance <= before));
    }

    receive() external payable { }
}

